+    expect(needsClauseDerivation("prose dump")).toBe(true);
+    expect(needsClauseDerivation({ commands: [], none_stated: true })).toBe(true);
+    expect(
+      needsClauseDerivation({
+        commands: [{ command: "pnpm test" }],
+        none_stated: false,
+        source_rung: "stated",
